def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_599: no hunk on ' + rel)
    for s in ABSENT.get(rel, []):
        if s in txt:
            raise SystemExit('ashira_599: FATAL: the live %s already holds %r; read it before releasing' % (rel, s))
    for old, new, n in HUNKS[rel]:
        if new in txt:
            raise SystemExit('ashira_599: FATAL: the live %s already holds the new text' % rel)
        k = txt.count(old)
        if k != n:
            raise SystemExit('ashira_599: FATAL: anchor x%d (want %d) in the live %s: %r' % (k, n, rel, old[:90]))
        txt = txt.replace(old, new)
    return txt


